package com.mushafi.qa;
import android.app.*;import android.content.*;import android.location.*;import android.os.*;import com.mushafi.app.*;import org.json.*;import java.util.*;
final class AutomaticLocationChecks {
 static void need(boolean yes,String why)throws Exception{if(!yes)throw new Exception(why);}
 static Location fix(double lat,double lon){Location l=new Location(LocationManager.GPS_PROVIDER);l.setLatitude(lat);l.setLongitude(lon);l.setAccuracy(20);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());return l;}
 static void run(Instrumentation i)throws Exception{Context c=i.getTargetContext();android.content.SharedPreferences saved=c.getSharedPreferences("prayer_times",0),automatic=c.getSharedPreferences("automatic_location",0);String oldPrayer=saved.getString("settings",null),oldFix=automatic.getString("fix",null);TimeZone zone=TimeZone.getDefault();AutomaticLocation[] controller={null};try{
 need(AutomaticLocation.permission(c),"location permission granted for native test");automatic.edit().clear().commit();PrayerSettings base=new PrayerSettings(new JSONObject());base.json.put("enabled",false).put("voice","nafees").put("asr","HANAFI");base.row("fajr").put("iqama",27);base.save(c);JSONObject plan=KhatmaScheduler.load(c);String beforePlan=plan==null?"":plan.toString();
 i.runOnMainSync(()->{controller[0]=new AutomaticLocation(c,()->{});controller[0].start();});need(controller[0].status().optBoolean("listening"),"foreground provider subscribed");
 Location riyadh=fix(24.7136,46.6753);i.runOnMainSync(()->controller[0].accept(riyadh));PrayerSettings first=PrayerSettings.load(c);need(Math.abs(first.json.getDouble("latitude")-24.7136)<.00001,"first fix saved");need(first.json.optBoolean("confirmed"),"automatic fix confirms shared location");long firstFajr=PrayerCalculator.snapshot(first,System.currentTimeMillis()).getJSONArray("days").getJSONObject(1).getLong("fajr");
 Location jitter=fix(24.7138,46.6754);i.runOnMainSync(()->controller[0].accept(jitter));need(PrayerSettings.load(c).json.getDouble("latitude")==first.json.getDouble("latitude"),"small jitter does not move prayer anchor");
 Location jeddah=fix(21.5433,39.1728);i.runOnMainSync(()->controller[0].accept(jeddah));PrayerSettings moved=PrayerSettings.load(c);need(Math.abs(moved.json.getDouble("latitude")-21.5433)<.00001,"travel updates automatically");need(PrayerCalculator.snapshot(moved,System.currentTimeMillis()).getJSONArray("days").getJSONObject(1).getLong("fajr")!=firstFajr,"prayer times recalculated after travel");need(moved.json.optString("voice").equals("nafees")&&moved.json.optString("asr").equals("HANAFI")&&moved.row("fajr").getInt("iqama")==27,"prayer preferences preserved");
 i.runOnMainSync(()->controller[0].setPrecise(true));Location nearby=fix(21.5439,39.1728);i.runOnMainSync(()->controller[0].accept(nearby));moved=PrayerSettings.load(c);need(Math.abs(moved.json.getDouble("latitude")-21.5439)<.00001,"qibla mode follows nearby movement");i.runOnMainSync(()->controller[0].setPrecise(false));
 PrayerSettings foreign=new PrayerSettings(new JSONObject().put("latitude",40).put("longitude",-74));PrayerSettings local=AutomaticLocation.overlay(c,foreign);need(local.json.getDouble("latitude")==moved.json.getDouble("latitude"),"account coordinates do not replace this device");
 Location stale=fix(40,-74);stale.setTime(System.currentTimeMillis()-600000);stale.setElapsedRealtimeNanos(Math.max(1,SystemClock.elapsedRealtimeNanos()-600000000000L));need(!AutomaticLocation.fresh(stale),"stale cache rejected");i.runOnMainSync(()->controller[0].accept(stale));need(PrayerSettings.load(c).json.getDouble("latitude")==moved.json.getDouble("latitude"),"stale fix does not change location");
 i.runOnMainSync(()->controller[0].stop());need(!controller[0].status().optBoolean("listening"),"listeners stop outside foreground");Location background=fix(30,31);i.runOnMainSync(()->controller[0].accept(background));need(PrayerSettings.load(c).json.getDouble("latitude")==moved.json.getDouble("latitude"),"no updates accepted in background");
 TimeZone.setDefault(TimeZone.getTimeZone("Europe/Istanbul"));i.runOnMainSync(()->controller[0].start());need(PrayerSettings.load(c).json.optString("timezone").equals("Europe/Istanbul"),"timezone refreshed on resume");JSONObject after=KhatmaScheduler.load(c);need(beforePlan.equals(after==null?"":after.toString()),"khatma unchanged");
 }finally{if(controller[0]!=null)i.runOnMainSync(()->controller[0].stop());TimeZone.setDefault(zone);android.content.SharedPreferences.Editor p=saved.edit();if(oldPrayer==null)p.remove("settings");else p.putString("settings",oldPrayer);p.commit();android.content.SharedPreferences.Editor a=automatic.edit();if(oldFix==null)a.remove("fix");else a.putString("fix",oldFix);a.commit();PrayerScheduler.schedule(c);}}
}
